    "ch6_s06_settlement_throw": {
        "id": "ch6_s06_settlement_throw",
        "chapter": 6,
        "chapterOrder": 6,
        "stageClass": "town_scene",
        "background": "casino main table with guest dice, Lorne's collateral page, and one visible contract anchor",
        "worldState": "Chapter 6 town return after the unresolved old-road search; Vesper settles suspected disloyalty under house rules",
        "viewpoint": "protagonist_limited",
        "knowledgeBoundary": null,
        "participantsRaw": "casino_owner, casino_dealer",
        "entry": "the player returns from the perimeter; Vesper immediately calls the witnessed settlement held since the Chapter 5 montage",
        "exit": "first run saves Lorne but lets Vesper escape; second run opens host/guest reversal",
        "objective": "prevent Lorne's life from being collected and expose the current-run loaded guest set",
        "inputsRaw": "casino showcase route; Blank Collateral clue; `莊家離席` only in second run",
        "outputsRaw": "first-run Vesper escape and Loaded Dice evidence; second-run marked guest set and final wager gate",
        "assetNotes": "reuse casino table/portrait assets; contract collection has no named Void creature or asset",
        "beats": [
            {
                "order": 1,
                "condition": "any",
                "beat": "narration",
                "actorId": null,
                "expression": null,
                "text": "你從山路返城時，主桌仍只留兩個位置。維斯珀坐在莊家側，洛恩站在客方，抵押頁壓在骰盅下；契約要求的見證人終於回來，客方骰仍比公開桌的同款稍重。"
            },
            {
                "order": 2,
                "condition": "any",
                "beat": "enter",
                "actorId": null,
                "expression": null,
                "text": "Casino owner and dealer enter; Lorne's usual table smile is absent."
            },
            {
                "order": 3,
                "condition": "any",
                "beat": "speaker",
                "actorId": "casino_owner",
                "expression": "soft",
                "text": "我們不談背叛，只談未結清的債。你想活著離桌，當然可以。贏一次就好。"
            },
            {
                "order": 4,
                "condition": "any",
                "beat": "speaker",
                "actorId": "casino_dealer",
                "expression": "guarded",
                "text": "客方要求見證人。規則第七行。"
            },
            {
                "order": 5,
                "condition": "any",
                "beat": "narration",
                "actorId": null,
                "expression": null,
                "text": "維斯珀允許你站在桌側。他知道見證不會改變被動過手腳的骰子，反而讓結果更像自願。"
            },
            {
                "order": 6,
                "condition": "any",
                "beat": "speaker",
                "actorId": "casino_owner",
                "expression": "pleased",
                "text": "公平？當然公平。每個人都有輸光的權利。"
            },
            {
                "order": 7,
                "condition": "first_run",
                "beat": "narration",
                "actorId": null,
                "expression": null,
                "text": "洛恩握住骰盅。你看見他拇指掂過重量，卻不知道那與契約如何相連。骰子離手前，你撞開桌側錨釘，結算線中斷。"
            },
            {
                "order": 8,
                "condition": "first_run",
                "beat": "speaker",
                "actorId": "casino_owner",
                "expression": "angry",
                "text": "你救下的只是一筆會重新到期的債。別把延後當成勝利。"
            },
            {
                "order": 9,
                "condition": "first_run",
                "beat": "narration",
                "actorId": null,
                "expression": null,
                "text": "維斯珀撕開抵押頁邊緣。紙後不是門，只是一道吞掉深度的黑縫；他帶著主契約離開，空白債權人沒有顯形。"
            },
            {
                "order": 10,
                "condition": "first_run",
                "beat": "exit",
                "actorId": null,
                "expression": null,
                "text": "Vesper escapes; Lorne survives; continue to house aftermath and Loaded Die handoff."
            },
            {
                "order": 11,
                "condition": "second_run",
                "beat": "narration",
                "actorId": null,
                "expression": null,
                "text": "`莊家離席` 讓你在骰盅落桌前認出異常重量。你要求依公開規則驗骰；洛恩把客方骰逐一轉到有細小刻痕的一面。"
            },
            {
                "order": 12,
                "condition": "second_run",
                "beat": "speaker",
                "actorId": "casino_dealer",
                "expression": "resolute",
                "text": "客方組，三枚，全重。不是每次都輸；只是每一次，都比莊家更接近輸。"
            },
            {
                "order": 13,
                "condition": "second_run",
                "beat": "narration",
                "actorId": null,
                "expression": null,
                "text": "你引用維斯珀自己寫下的爭議條款：莊家若拒絕以同一組器具交換客位證明公平，所有私人抵押立即失效，主人席與總帳交由城鎮清查。接受交換，才能保住屋子與契約主張。"
            },
            {
                "order": 14,
                "condition": "second_run",
                "beat": "speaker",
                "actorId": "casino_owner",
                "expression": "pleased",
                "text": "要我為三顆重一點的骰子交出整間屋子？不。一局而已。我只需要贏一次。"
            },
            {
                "order": 15,
                "condition": "second_run",
                "beat": "exit",
                "actorId": null,
                "expression": null,
                "text": "Lock marked guest set; open `house_changes_seats` final wager with Vesper unable to remove the witnessed dice."
            }
        ]
    },
